use vstd::prelude::*;

verus! {

  /// Given a non‐empty Vec<char> `t`, produce a new Vec<char> of the
  /// same length whose i-th character equals t[i].
  pub fn solve(t: Vec<char>) -> Vec<char>
    requires
      // input must be non‐empty
      t.len() >= 1,
    ensures
      // output has same length as input
      |res: Vec<char>| res.len() == t.len()
                      // and every character is carried over
                      && forall |i: usize| i < t.len() ==> res[i] == t[i],
  {
    let n: usize = t.len();
    let mut res: Vec<char> = Vec::new();
    let mut i: usize = 0;

    // Loop until we've copied all n characters.
    // Invariants:
    //   1) 0 ≤ i ≤ n
    //   2) res.len() == i
    //   3) for all 0 ≤ j < i, res[j] == t[j]
    // Decreases measure (n ‑ i) to prove termination.
    while i < n
      invariant
        0 <= i && i <= n,
      invariant
        res.len() == i,
      invariant
        forall |j: usize| j < i ==> res[j] == t[j],
      decreases
        n - i,
    {
      res.push(t[i]);
      i += 1;
    }

    res
  }

}